def _legacy_number(value) -> float:
    """Coerce a legacy numeric value, treating missing and empty values as zero."""
    if value is None:
        return 0.0
    if isinstance(value, str):
        if value.strip() == "":
            return 0.0
    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Perform legacy division, logging SCRIPT_DIV0 for a zero divisor."""
    numerator = _legacy_number(a)
    denominator = _legacy_number(b)

    if denominator == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return numerator / denominator, []
    except (ArithmeticError, OverflowError):
        return 0.0, ["SCRIPT_DIV0"]
